<?php require_once 'auth.php';requiereRol('empleado');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['idCita']??0);$estado=$_POST['estado']??'';$resp=trim($_POST['respuesta']??'');if(in_array($estado,['Aceptada','Rechazada'],true)){$q=$conexion->prepare("UPDATE citas SET estado=?,respuesta=?,atendidaPor=? WHERE idCita=? AND estado='Pendiente'");$q->execute([$estado,$resp,$_SESSION['idUsuario'],$id]);$msg=$q->rowCount()?'La solicitud fue actualizada.':'La cita ya no está pendiente.';}}$rows=$conexion->query("SELECT c.*,m.nombre mascota,u.nombre cliente FROM citas c JOIN mascotas m ON m.idMascota=c.idMascota JOIN usuario u ON u.idUsuario=c.idUsuario ORDER BY (c.estado='Pendiente') DESC,c.fecha_cita,c.hora")->fetchAll();encabezado('Solicitudes de citas');alerta($msg);?><div class="table-wrap"><table><tr><th>Cliente</th><th>Mascota</th><th>Fecha y hora</th><th>Motivo</th><th>Estado</th><th>Resolver solicitud</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['cliente'])?></td><td><?=e($r['mascota'])?></td><td><?=e($r['fecha_cita'])?> · <?=e($r['hora'])?></td><td><?=e($r['motivo'])?></td><td><span class="status <?=strtolower($r['estado'])?>"><?=e($r['estado'])?></span></td><td><?php if($r['estado']==='Pendiente'):?><form method="post" class="resolve"><input type="hidden" name="idCita" value="<?=$r['idCita']?>"><input name="respuesta" placeholder="Comentario (opcional)"><button class="btn small" name="estado" value="Aceptada">Aceptar</button><button class="btn danger small" name="estado" value="Rechazada">Rechazar</button></form><?php else:?><?=e($r['respuesta']??'—')?><?php endif;?></td></tr><?php endforeach;?></table></div><?php pie();?>